MERGE INTO RH_PAKET_PRESET t USING (SELECT 'com.dan.soundscape' AS PAKET, 'Soundscape' AS KLASSE, 'calm' AS NAME FROM DUAL) q ON (t.PAKET = q.PAKET AND t.KLASSE = q.KLASSE AND t.NAME = q.NAME)
WHEN MATCHED THEN UPDATE SET t.BESCHREIBUNG = 'Preset calm() aus com.dan.soundscape' WHERE t.HERKUNFT = 'MITGELIEFERT'
